<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { Plus, Network, ArrowLeft, Pencil, Trash2, Users } from 'lucide-vue-next'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, allUsers, errorText, flattenDepartments, write } from '../api'
import { useAuth } from '../stores/auth'
import type { Department, User } from '../types'
import PageHeader from '../components/PageHeader.vue'
import MasterDetail from '../components/MasterDetail.vue'
import AsyncState from '../components/AsyncState.vue'
import FormDialog from '../components/FormDialog.vue'
import FieldInput from '../components/FieldInput.vue'
import UserAvatar from '../components/UserAvatar.vue'
const auth=useAuth(),tree=ref<Department[]>([]),people=ref<User[]>([]),selectedId=ref(''),flat=computed(()=>flattenDepartments(tree.value)),selected=computed(()=>flat.value.find(d=>d.id===selectedId.value))
const loading=ref(true),error=ref(''),members=ref<User[]>([]),memberTotal=ref(0),memberPage=ref(1),memberLoading=ref(false),memberError=ref(''),mobileDetail=ref(false)
let memberVersion=0
async function load(){loading.value=true;error.value='';try{tree.value=(await api.departments()).items;if(!flat.value.some(d=>d.id===selectedId.value))selectedId.value=flat.value[0]?.id||'';if(auth.has('org:user:read'))people.value=await allUsers();memberPage.value=1;await loadMembers()}catch(e){error.value=errorText(e)}finally{loading.value=false}}
async function loadMembers(){if(!selectedId.value||!auth.has('org:user:read'))return;const version=++memberVersion;memberLoading.value=true;memberError.value='';try{const r=await api.users({department_id:selectedId.value,page:memberPage.value,page_size:20});if(version===memberVersion){members.value=r.items;memberTotal.value=r.total}}catch(e){if(version===memberVersion)memberError.value=errorText(e)}finally{if(version===memberVersion)memberLoading.value=false}}
function choose(d:Department){selectedId.value=d.id;memberPage.value=1;mobileDetail.value=true;void loadMembers()}
onMounted(load)
const dialog=ref(false),editing=ref<Department|null>(null),busy=ref(false),formError=ref(''),form=reactive({code:'',name:'',parent_id:'',leader_id:'',sort_order:0})
function open(d?:Department){editing.value=d||null;Object.assign(form,{code:d?.code||'',name:d?.name||'',parent_id:d?.parent_id||'',leader_id:d?.leader_id||'',sort_order:d?.sort_order||0});formError.value='';dialog.value=true}
function descendant(d:Department,ancestor:string):boolean{return d.id===ancestor||!!d.parent_id&&!!flat.value.find(p=>p.id===d.parent_id)&&descendant(flat.value.find(p=>p.id===d.parent_id)!,ancestor)}
const parentOptions=computed(()=>flat.value.filter(d=>!editing.value||!descendant(d,editing.value.id)))
async function save(){busy.value=true;formError.value='';try{const result=await write<Department>(editing.value?`/org/departments/${editing.value.id}`:'/org/departments',{...form,parent_id:form.parent_id||null,leader_id:form.leader_id||null},editing.value?'PUT':'POST');selectedId.value=result.id;dialog.value=false;await load();ElMessage.success('部门已保存')}catch(e){formError.value=errorText(e)}finally{busy.value=false}}
async function remove(){if(!selected.value)return;try{await ElMessageBox.confirm('仍有下级部门、成员或知识授权时不能删除。',`删除「${selected.value.name}」`,{confirmButtonText:'确认删除',cancelButtonText:'取消'});await write(`/org/departments/${selectedId.value}`,undefined,'DELETE');selectedId.value='';await load();ElMessage.success('部门已删除')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(errorText(e))}}
const memberDialog=ref(false),chosenUser=ref('')
async function moveMember(){const user=people.value.find(u=>u.id===chosenUser.value);if(!user)return;busy.value=true;formError.value='';try{await write(`/org/users/${user.id}`,{display_name:user.display_name,email:user.email,department_id:selectedId.value},'PUT');memberDialog.value=false;await load();ElMessage.success('成员部门已更新')}catch(e){formError.value=errorText(e)}finally{busy.value=false}}
</script>
<template>
  <PageHeader title="部门管理" description="梳理组织层级，明确每位成员的直属部门。"><button v-if="auth.has('org:department:create')" class="button primary" @click="open()"><Plus :size="17"/>新增部门</button></PageHeader>
  <AsyncState :loading="loading" :error="error" :empty="!flat.length" empty-text="尚未建立部门" @retry="load"><MasterDetail :show-detail="mobileDetail"><template #master><div class="section-label"><span>组织架构</span><span class="num">{{flat.length}} 个部门</span></div><div role="list" aria-label="部门树"><button v-for="d in flat" :key="d.id" class="department-row" :class="{selected:d.id===selectedId}" :style="{paddingLeft:`${12+d.depth*16}px`}" @click="choose(d)"><Network :size="16"/><span>{{d.name}}</span><span class="num muted">{{d.member_count}}</span></button></div><p class="pane-note">数字为直属成员数。知识授权仅匹配明确指定的部门。</p></template><template v-if="selected"><button class="text-button mobile-back" @click="mobileDetail=false"><ArrowLeft :size="16"/>返回部门树</button><div class="detail-head"><div><h2>{{selected.name}}</h2><p class="muted">{{selected.code}}</p></div><div class="detail-actions"><button v-if="auth.has('org:department:update')" class="button" @click="open(selected)"><Pencil :size="15"/>编辑部门</button><button v-if="auth.has('org:department:delete')" class="icon-button" aria-label="删除部门" @click="remove"><Trash2 :size="16"/></button></div></div><dl class="department-facts"><div><dt>上级部门</dt><dd>{{flat.find(d=>d.id===selected?.parent_id)?.name||'根部门'}}</dd></div><div><dt>负责人</dt><dd>{{people.find(u=>u.id===selected?.leader_id)?.display_name||(selected.leader_id?'已设置负责人':'未设置')}}</dd></div><div><dt>直属成员</dt><dd class="num">{{selected.member_count}} <span>人</span></dd></div></dl><div class="section-head"><h2>直属成员</h2><button v-if="auth.has('org:user:update')&&auth.has('org:user:read')" class="text-button" @click="memberDialog=true;chosenUser='';formError='' "><Plus :size="16"/>添加成员</button></div><p v-if="!auth.has('org:user:read')" class="empty-state">成员详情需要查看用户权限。</p><AsyncState v-else :loading="memberLoading" :error="memberError" :empty="!members.length" empty-text="这个部门还没有直属成员" @retry="loadMembers"><div class="member-list"><div v-for="u in members" :key="u.id" class="member-row"><div class="person"><UserAvatar :name="u.display_name" :identity="u.id"/><div><strong>{{u.display_name}}</strong><small>{{u.username}}</small></div></div><span class="muted">{{u.roles.map(r=>r.role_name).join('、')||'未分配角色'}}</span><span class="status" :class="u.status"><span></span>{{u.status==='active'?'启用':'停用'}}</span></div></div><div v-if="memberTotal>20" class="pagination"><button class="button" :disabled="memberPage===1" @click="memberPage--;loadMembers()">上一页</button><span class="num">{{memberPage}} / {{Math.ceil(memberTotal/20)}}</span><button class="button" :disabled="memberPage*20>=memberTotal" @click="memberPage++;loadMembers()">下一页</button></div></AsyncState><div class="context-note"><Users :size="17"/><span>成员只能归属一个直属部门，调整后会立即更新其部门权限。</span></div></template></MasterDetail></AsyncState>
  <FormDialog :open="dialog" :title="editing?'编辑部门':'新增部门'" :busy="busy" :error="formError" @close="dialog=false" @submit="save"><FieldInput v-slot="{id}" label="部门名称" required><input :id="id" v-model="form.name" required maxlength="100"/></FieldInput><FieldInput v-slot="{id}" label="部门编码" required hint="小写字母、数字、下划线、短横线或点。"><input :id="id" v-model="form.code" required pattern="[a-z0-9][a-z0-9_.-]*" maxlength="64"/></FieldInput><FieldInput v-slot="{id}" label="上级部门"><select :id="id" v-model="form.parent_id"><option value="">根部门</option><option v-for="d in parentOptions" :key="d.id" :value="d.id">{{'　'.repeat(d.depth)}}{{d.name}}</option></select></FieldInput><FieldInput v-slot="{id}" label="负责人"><select :id="id" v-model="form.leader_id" :disabled="!auth.has('org:user:read')"><option value="">未设置负责人</option><option v-for="u in people.filter(u=>u.status==='active'||u.id===form.leader_id)" :key="u.id" :value="u.id">{{u.display_name}} · {{u.username}}</option><option v-if="form.leader_id&&!people.some(u=>u.id===form.leader_id)" :value="form.leader_id">保留当前负责人</option></select></FieldInput><FieldInput v-slot="{id}" label="显示顺序"><input :id="id" v-model.number="form.sort_order" type="number" min="0" max="100000" required/></FieldInput></FormDialog>
  <FormDialog :open="memberDialog" title="添加直属成员" :busy="busy" :error="formError" @close="memberDialog=false" @submit="moveMember"><p class="dialog-subtitle">将所选用户的直属部门调整为「{{selected?.name}}」。原部门授权将不再适用。</p><FieldInput v-slot="{id}" label="选择成员" required><select :id="id" v-model="chosenUser" required><option value="" disabled>选择组织中的用户</option><option v-for="u in people.filter(u=>u.department_id!==selectedId)" :key="u.id" :value="u.id">{{u.display_name}} · {{u.department?.name||'未分配部门'}}</option></select></FieldInput></FormDialog>
</template>
